// LA FORMATION MÉTIER « lawyer » (juriste) · voir ./types.
//
// Le cycle réel du métier : un contrat arrive sur le bureau (on le protège, on
// le lit, on le passe au crible), on rédige et on renégocie des clauses, puis
// on répond à une question de droit par une recherche et une note. Les deux
// contraintes qui traversent les neuf dojos : le secret professionnel (rien de
// confidentiel dans un outil non approuvé) et la vérification de chaque source
// dans une base officielle, parce qu'un modèle peut inventer une jurisprudence.
import { B } from '../bilingual'
import type { Level, Module } from '../curriculum'
import type { Enrichment } from '../enrich/types'
import type { Deepening } from '../deep/types'
import type { TradePack } from './types'

const TINT = '#b45309'

